-- ── Hand-written: rules Prisma's schema language cannot express ───────────────
ALTER TABLE "chat_drafts"
  -- A failure always has a cause, and a success never does.
  ADD CONSTRAINT "chat_drafts_error_iff_failed" CHECK (("outcome" = 'OK') = ("error_code" IS NULL)),
  ADD CONSTRAINT "chat_drafts_message_chars_non_negative" CHECK ("message_chars" >= 0),
  ADD CONSTRAINT "chat_drafts_confidence_range" CHECK ("confidence" IS NULL OR ("confidence" >= 0 AND "confidence" <= 1)),
  ADD CONSTRAINT "chat_drafts_attempts_range" CHECK ("attempts" IS NULL OR "attempts" IN (1, 2)),
  ADD CONSTRAINT "chat_drafts_error_detail_size" CHECK ("error_detail" IS NULL OR length("error_detail") <= 4000);

-- Row-level security enabled with NO policies, like every other table: blocks Supabase's public Data API.
ALTER TABLE "chat_drafts" ENABLE ROW LEVEL SECURITY;
